public class RagdollSimulator {
    private static final int WIDTH = 800;
    private static final int HEIGHT = 600;

    public static void main(String[] args) {
        JFrame frame = new JFrame("Machine Minds Manipulator");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(WIDTH, HEIGHT);

        Ragdoll ragdoll = new Ragdoll();
        ragdoll.setLocationRelativeTo(frame); // Center the ragdoll within the window
        ragdoll.setVisible(true);
    }

    static class Ragdoll extends JPanel {
        private int x = 0;
        private int y = 0;
        private int speedX = 5;
        private int speedY = 5;

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            g.setColor(Color.RED);
            g.fillOval(x, y, 50, 50);
        }

        public void move() {
            x += speedX;
            y += speedY;

            if (x < 0 || x > WIDTH - 50) {
                speedX *= -1; // Reverse direction horizontally
            }
            if (y < 0 || y > HEIGHT - 50) {
                speedY *= -1; // Reverse direction vertically
            }
        }
    }
}
